function startOfDay(d){const x=new Date(d);x.setHours(12,0,0,0);return x}
function iso(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function faNum(v){return String(v).replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d])}
function jalali(d){return new Intl.DateTimeFormat('fa-IR-u-ca-persian',{year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function weekday(d){return new Intl.DateTimeFormat('fa-IR',{weekday:'long'}).format(d)}
function addDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return startOfDay(x)}
function diffDays(a,b){return Math.round((startOfDay(a)-startOfDay(b))/86400000)}
function isAlternateDue(d){return Math.abs(diffDays(d,anchor))%2===0}
function customItems(){return data.settings.customItems.filter(i=>i.active!==false)}
function dailyCustom(){return customItems().filter(i=>i.kind!=='nutrition'&&!['weekly','monthly'].includes(i.schedule)).map(i=>({...i,alternate:i.schedule==='alternate',scoreType:i.scoreType||'tri',hint:`${i.category} · هدف ${faNum(i.target)} ${i.unit}${i.time?` · ساعت ${i.time}`:''}`}))}
function weeklyCustom(){return customItems().filter(i=>i.schedule==='weekly')}
function monthlyCustom(){return customItems().filter(i=>i.schedule==='monthly')}
function exerciseItems(){return [...(data.settings.showLegacyDefaults?builtInExercises:[]),...dailyCustom()]}
function nutritionItems(){return[...(data.settings.showLegacyDefaults?builtInNutrition:[]),...customItems().filter(i=>i.kind==='nutrition').map(i=>({...i,hint:`${i.category} · هدف ${faNum(i.target)} ${i.unit}${i.time?` · ساعت ${i.time}`:''}`}))]}
function weekStart(d){const x=startOfDay(d);const day=x.getDay();const offset=(day+1)%7;return addDays(x,-offset)}
function getDay(key=iso(selectedDate)){return data.days[key]||(data.days[key]={scores:{},note:''})}
function getWeek(d=selectedDate){const start=weekStart(d),key=iso(start);return data.weeks[key]||(data.weeks[key]={cardio:0,hypnosis:0,omega:0})}
function monthKey(d=selectedDate){const parts=new Intl.DateTimeFormat('en-US-u-ca-persian',{year:'numeric',month:'2-digit'}).formatToParts(d);return `${parts.find(x=>x.type==='year').value}-${parts.find(x=>x.type==='month').value}`}
function getMonth(d=selectedDate){const key=monthKey(d);return data.months[key]||(data.months[key]={})}
function itemScoreRatio(item,value){if(item.scoreType==='five')return Math.min(1,(Number(value)||0)/5);if(['counter','duration'].includes(item.scoreType))return Math.min(1,(Number(value)||0)/Math.max(1,Number(item.target)||1));if(item.scoreType==='binary')return value===true||Number(value)>=1?1:0;return Math.min(1,Number(value)||0)}
function scoreFor(items,day,date){const due=items.filter(i=>!i.alternate||isAlternateDue(date));const sum=due.reduce((s,i)=>s+itemScoreRatio(i,day.scores[i.id]),0);return due.length?sum/due.length:0}
function dayScore(date){const day=data.days[iso(date)];if(!day)return{exercise:0,nutrition:0,total:0,recorded:false};const exercise=scoreFor(exerciseItems(),day,date),food=scoreFor(nutritionItems(),day,date);const recorded=Object.keys(day.scores||{}).length>0;return{exercise,nutrition:food,total:(exercise+food)/2,recorded}}
function pct(v){return `${faNum(Math.round(v*100))}٪`}

function habitScoreControl(item,value,type){const base=`data-id="${item.id}" data-type="${type}"`;if(item.scoreType==='binary')return`<div class="score-buttons">${[['0','انجام نشد'],['1','انجام شد']].map(([v,l])=>`<button class="score-button ${String(value)===v?'selected':''}" ${base} data-score="${v}">${l}</button>`).join('')}</div>`;if(item.scoreType==='five')return`<div class="course-score-buttons five">${[1,2,3,4,5].map(v=>`<button class="${Number(value)===v?'selected':''}" ${base} data-score="${v}">${faNum(v)}</button>`).join('')}</div>`;if(['counter','duration'].includes(item.scoreType))return`<div class="course-counter"><button ${base} data-item-delta="-1">−</button><strong>${faNum(Number(value)||0)}</strong><span>از ${faNum(item.target)} ${escapeHtml(item.unit)}</span><button ${base} data-item-delta="1">+</button></div>`;return`<div class="score-buttons">${[['0','انجام نشد'],['0.5','ناقص'],['1','کامل']].map(([v,l])=>`<button class="score-button ${String(value)===v?'selected':''}" ${base} data-score="${v}">${l}</button>`).join('')}</div>`}
function renderHabitList(container,items,type){const day=getDay();container.innerHTML='';items.forEach(item=>{const due=!item.alternate||isAlternateDue(selectedDate);const row=document.createElement('div');row.className=`habit-row${due?'':' not-due'}`;const value=day.scores[item.id];row.innerHTML=`<div class="habit-head"><div><strong>${escapeHtml(item.name)}</strong><small>${escapeHtml(item.hint||'')}</small>${item.description?`<p class="habit-description">${escapeHtml(item.description)}</p>`:''}</div>${due?'':'<span class="not-due-badge">موعد نیست</span>'}</div>${habitScoreControl(item,value,type)}`;container.appendChild(row)});}
function renderToday(){document.getElementById('weekday').textContent=weekday(selectedDate);document.getElementById('jalaliDate').textContent=jalali(selectedDate);renderHabitList(document.getElementById('exerciseList'),exerciseItems(),'exercise');renderHabitList(document.getElementById('nutritionList'),nutritionItems(),'nutrition');const s=dayScore(selectedDate);document.getElementById('exerciseMiniScore').textContent=pct(s.exercise);document.getElementById('nutritionMiniScore').textContent=pct(s.nutrition);document.getElementById('totalScore').textContent=pct(s.total);document.getElementById('scoreRing').style.setProperty('--score',Math.round(s.total*100));document.getElementById('dayStatus').textContent=!s.recorded?'هنوز ثبت نشده':s.total>=.8?'روز خیلی خوب':s.total>=.5?'در مسیر پیشرفت':'نیاز به توجه';document.getElementById('scoreCaption').textContent=!s.recorded?'با یک لمس وضعیت تمرین‌ها را ثبت کن.':`${faNum(Object.keys(getDay().scores).length)} مورد برای این روز ثبت شده است.`;document.getElementById('dayNote').value=getDay().note||'';renderTodayCourses();renderWeekly();renderMonthly();}
function renderWeekly(){const start=weekStart(selectedDate),end=addDays(start,6),w=getWeek();document.getElementById('weekRange').textContent=`${jalali(start)} تا ${jalali(end)}`;document.querySelectorAll('[data-legacy-weekly]').forEach(x=>x.hidden=!data.settings.showLegacyDefaults);['cardio','hypnosis','omega'].forEach(k=>document.getElementById(`${k}Count`).textContent=faNum(w[k]||0));document.getElementById('omegaStatus').textContent=w.omega<2?'برنامه: ۲ تا ۴ عدد':w.omega<=4?'در محدوده برنامه':'بیشتر از محدوده برنامه';document.querySelectorAll('.custom-weekly').forEach(x=>x.remove());const grid=document.querySelector('.counter-grid');weeklyCustom().forEach(item=>{const card=document.createElement('label');card.className='counter-card custom-weekly';card.innerHTML=`<span>${escapeHtml(item.name)}</span><small>${escapeHtml(item.category)} · هدف: ${faNum(item.target)} ${escapeHtml(item.unit)}${item.time?` · ساعت ${item.time}`:''}</small>${item.description?`<p class="habit-description">${escapeHtml(item.description)}</p>`:''}<div class="counter"><button data-counter="${item.id}" data-delta="-1">−</button><strong id="${item.id}Count">${faNum(w[item.id]||0)}</strong><button data-counter="${item.id}" data-delta="1">+</button></div>`;grid.appendChild(card)});}
function renderMonthly(){const items=monthlyCustom(),month=getMonth(),grid=document.getElementById('monthlyGrid');document.getElementById('monthRange').textContent=faNum(monthKey(selectedDate).replace('-', '/'));document.getElementById('emptyMonthly').hidden=items.length>0;grid.innerHTML='';items.forEach(item=>{const card=document.createElement('label');card.className='counter-card';card.innerHTML=`<span>${escapeHtml(item.name)}</span><small>${escapeHtml(item.category)} · هدف: ${faNum(item.target)} ${escapeHtml(item.unit)}${item.time?` · ساعت ${item.time}`:''}</small>${item.description?`<p class="habit-description">${escapeHtml(item.description)}</p>`:''}<div class="counter"><button data-month-counter="${item.id}" data-delta="-1">−</button><strong>${faNum(month[item.id]||0)}</strong><button data-month-counter="${item.id}" data-delta="1">+</button></div>`;grid.appendChild(card)})}
function setScore(id,value){const day=getDay();day.scores[id]=Number(value);saveData();renderToday();}
function changeDailyItemValue(id,delta){const day=getDay();day.scores[id]=Math.max(0,Math.min(9999,(Number(day.scores[id])||0)+delta));saveData();renderToday()}
function changeCounter(key,delta){const w=getWeek();w[key]=Math.max(0,Math.min(99,(w[key]||0)+delta));saveData();renderWeekly();}
function changeMonthCounter(key,delta){const m=getMonth();m[key]=Math.max(0,Math.min(999,(m[key]||0)+delta));saveData();renderMonthly()}
function renderTrend(){const dates=Array.from({length:7},(_,i)=>addDays(startOfDay(new Date()),i-6));const chart=document.getElementById('trendChart');chart.innerHTML='';let total=0,recorded=0,best=null;dates.forEach(d=>{const s=dayScore(d);if(s.recorded){total+=s.total;recorded++;if(!best||s.total>best.score)best={date:d,score:s.total}}const item=document.createElement('div');item.className='bar-item';item.innerHTML=`<span class="bar-value">${s.recorded?pct(s.total):'—'}</span><div class="bar-track"><div class="bar-fill" style="height:${Math.max(2,s.total*100)}%"></div></div><span class="bar-label">${weekday(d).replace('شنبه','ش').replace('یکشنبه','ی').replace('دوشنبه','د').replace('سه‌شنبه','س').replace('چهارشنبه','چ').replace('پنجشنبه','پ').replace('جمعه','ج')}</span>`;chart.appendChild(item)});document.getElementById('sevenDayAverage').textContent=pct(recorded?total/recorded:0);document.getElementById('recordedDays').textContent=faNum(recorded);document.getElementById('bestDay').textContent=best?weekday(best.date):'—';document.getElementById('streakCount').textContent=`${faNum(calculateStreak())} روز`;const history=document.getElementById('historyList');history.innerHTML='';dates.slice().reverse().forEach(d=>{const s=dayScore(d);const row=document.createElement('div');row.className='history-row';row.innerHTML=`<div><strong>${weekday(d)}</strong><span> · ${jalali(d)}</span></div><strong>${s.recorded?pct(s.total):'ثبت نشده'}</strong>`;history.appendChild(row)});}
function calculateStreak(){let count=0,d=startOfDay(new Date());for(let i=0;i<365;i++){if(dayScore(d).recorded){count++;d=addDays(d,-1)}else break}return count}
function csvEscape(v){return `"${String(v??'').replaceAll('"','""')}"`}
function exportCsv(){const allExercise=[...(data.settings.showLegacyDefaults?builtInExercises:[]),...data.settings.customItems.filter(i=>i.kind!=='nutrition'&&!['weekly','monthly'].includes(i.schedule))],allNutrition=nutritionItems();const header=['تاریخ شمسی','روز',...allExercise.map(x=>x.name),...allNutrition.map(x=>x.name),'امتیاز تمرین','امتیاز تغذیه','امتیاز کل','یادداشت'];const rows=Object.keys(data.days).sort().map(key=>{const d=new Date(`${key}T12:00:00`),day=data.days[key],s=dayScore(d);return[jalali(d),weekday(d),...allExercise.map(x=>day.scores?.[x.id]??''),...allNutrition.map(x=>day.scores?.[x.id]??''),Math.round(s.exercise*100),Math.round(s.nutrition*100),Math.round(s.total*100),day.note||'']});download('\ufeff'+[header,...rows].map(r=>r.map(csvEscape).join(',')).join('\n'),'tamrin-yar.csv','text/csv;charset=utf-8')}
function download(content,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2200)}
function switchView(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===id));if(id==='trendView')renderTrend();if(id==='manageView')renderManage();if(id==='libraryView')renderLibrary();if(id==='coursesView')renderCourses();if(id==='dataView')renderReminderSettings();if(id==='coachView')loadCoachView();window.scrollTo({top:0,behavior:'smooth'})}

function scheduleLabel(item){return item.schedule==='daily'?'روزانه':item.schedule==='alternate'?'یک روز در میان':`${item.schedule==='monthly'?'ماهانه':'هفتگی'} · هدف ${faNum(item.target)} ${item.unit}`}
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function renderLibrary(){const list=document.getElementById('libraryList');list.innerHTML='';libraryItems.forEach(item=>{const added=customItems().some(x=>x.libraryId===item.id);const card=document.createElement('article');card.className='library-card';card.innerHTML=`<h3>${escapeHtml(item.title_fa)}</h3><span class="library-meta">${escapeHtml(item.category)} · ${escapeHtml(scheduleLabel(item))}</span><p>${escapeHtml(item.description_fa)}</p>${item.caution_fa?`<p class="library-caution">نکته: ${escapeHtml(item.caution_fa)}</p>`:''}<div class="library-actions"><button data-add-library="${escapeHtml(item.id)}" ${added?'disabled':''}>${added?'در برنامهٔ شماست':'+ افزودن به برنامه'}</button>${isOwnerSession()?`<button class="library-edit" data-edit-library="${escapeHtml(item.id)}">ویرایش توضیحات</button>`:''}</div>`;list.appendChild(card)})}
function addFromLibrary(id){const item=libraryItems.find(x=>x.id===id);if(!item||customItems().some(x=>x.libraryId===id))return;data.settings.customItems.push({id:`custom-${Date.now()}`,libraryId:item.id,name:item.title_fa,category:item.category,description:item.description_fa||'',schedule:item.schedule,target:item.target,unit:item.unit,time:'',scoreType:['weekly','monthly'].includes(item.schedule)?'counter':'tri',active:true});saveData();renderLibrary();renderToday();toast('تمرین به برنامه اضافه شد')}
function openLibraryEdit(id){const item=libraryItems.find(x=>x.id===id);if(!item||!isOwnerSession())return;document.getElementById('libraryEditId').value=item.id;document.getElementById('libraryEditTitle').textContent=`ویرایش «${item.title_fa}»`;document.getElementById('libraryEditDescription').value=item.description_fa||'';document.getElementById('libraryEditCaution').value=item.caution_fa||'';document.getElementById('libraryEditDialog').showModal()}
async function saveLibraryEdit(){if(!isOwnerSession())return false;const id=document.getElementById('libraryEditId').value,item=libraryItems.find(x=>x.id===id),description_fa=document.getElementById('libraryEditDescription').value.trim(),caution_fa=document.getElementById('libraryEditCaution').value.trim();if(!item||!description_fa)return false;const res=await cloudRequest(`/rest/v1/exercise_library?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({description_fa,caution_fa:caution_fa||null})});if(!res.ok){toast('ذخیره توضیحات ناموفق بود');return false}item.description_fa=description_fa;item.caution_fa=caution_fa||null;renderLibrary();toast('توضیحات بانک ذخیره شد');return true}
function renderManage(){const list=document.getElementById('customItemList'),items=customItems();list.innerHTML='';document.getElementById('emptyItems').hidden=items.length>0;items.forEach(item=>{const row=document.createElement('article');row.className='manage-item';row.innerHTML=`<span class="manage-badge">${escapeHtml(item.category.slice(0,2))}</span><div class="manage-copy"><strong>${escapeHtml(item.name)}</strong><span>${escapeHtml(item.category)} · ${escapeHtml(scheduleLabel(item))}${item.time?` · ${item.time}`:''}</span>${item.description?`<small>${escapeHtml(item.description)}</small>`:''}</div><div class="manage-actions"><button data-edit-item="${item.id}">ویرایش همه مشخصات</button><button class="archive" data-archive-item="${item.id}">بایگانی</button><button class="delete" data-delete-item="${item.id}">حذف</button></div>`;list.appendChild(row)})}
function openItemDialog(id){const item=id?data.settings.customItems.find(x=>x.id===id):null;document.getElementById('dialogTitle').textContent=item?'ویرایش همه مشخصات':'افزودن فعالیت';document.getElementById('itemId').value=item?.id||'';document.getElementById('itemName').value=item?.name||'';document.getElementById('itemCategory').value=item?.category||'';document.getElementById('itemDescription').value=item?.description||'';document.getElementById('itemSchedule').value=item?.schedule||'daily';document.getElementById('itemTime').value=item?.time||'';document.getElementById('itemScoreType').value=item?.scoreType||(['weekly','monthly'].includes(item?.schedule)?'counter':'tri');document.getElementById('itemTarget').value=item?.target||1;document.getElementById('itemUnit').value=item?.unit||'بار';document.getElementById('itemDialog').showModal()}
function saveItem(){const id=document.getElementById('itemId').value||`custom-${Date.now()}`;const item={id,name:document.getElementById('itemName').value.trim(),category:document.getElementById('itemCategory').value.trim(),description:document.getElementById('itemDescription').value.trim(),schedule:document.getElementById('itemSchedule').value,time:document.getElementById('itemTime').value,scoreType:document.getElementById('itemScoreType').value,target:Math.max(1,Number(document.getElementById('itemTarget').value)||1),unit:document.getElementById('itemUnit').value.trim()||'بار',active:true};if(!item.name||!item.category)return false;const index=data.settings.customItems.findIndex(x=>x.id===id);if(index>=0)data.settings.customItems[index]={...data.settings.customItems[index],...item};else data.settings.customItems.push(item);saveData();renderManage();renderToday();toast(index>=0?'همه مشخصات فعالیت ویرایش شد':'فعالیت اضافه شد');return true}
function archiveItem(id){const item=data.settings.customItems.find(x=>x.id===id);if(!item)return;item.active=false;saveData();renderManage();renderToday();toast('فعالیت بایگانی شد؛ سوابق آن حفظ شده است')}
function deleteItem(id){const item=data.settings.customItems.find(x=>x.id===id);if(!item||!confirm(`«${item.name}» و همه ثبت‌های مربوط به آن برای همیشه حذف شود؟`))return;data.settings.customItems=data.settings.customItems.filter(x=>x.id!==id);Object.values(data.days).forEach(day=>{if(day.scores)delete day.scores[id]});Object.values(data.weeks).forEach(week=>delete week[id]);Object.values(data.months).forEach(month=>delete month[id]);saveData();renderManage();renderToday();toast('فعالیت و سوابق آن حذف شد')}

function courseDayNumber(course,date=startOfDay(new Date())){return Math.floor((date-startOfDay(new Date(`${course.start}T12:00:00`)))/86400000)+1}
function normalizeCourseItem(item,index,course){if(typeof item==='string')return{id:`ci-${index}`,name:item,description:'',schedule:course.pattern||'daily',scheduleValue:(course.weekdays||[]).join(','),time:'',scoreType:'binary',target:1,unit:'بار',required:true};return{id:item.id||`ci-${index}`,name:item.name||`تمرین ${index+1}`,description:item.description||'',schedule:item.schedule||'daily',scheduleValue:item.scheduleValue||'',time:item.time||'',scoreType:item.scoreType||'tri',target:Math.max(1,Number(item.target)||1),unit:item.unit||'بار',required:item.required!==false}}
function normalizeCourse(course){course.items=(course.items||[]).map((x,i)=>normalizeCourseItem(x,i,course));return course}
function courseItemDue(course,item,day,date){if(day<1||day>course.duration)return false;if(item.schedule==='odd')return day%2===1;if(item.schedule==='even')return day%2===0;if(item.schedule==='alternate')return day%2===1;if(item.schedule==='weekdays')return String(item.scheduleValue||'').split(',').map(Number).includes(date.getDay());if(item.schedule==='specific')return String(item.scheduleValue||'').split(',').map(Number).includes(day);return true}
function courseItemsDue(course,date=selectedDate){const day=courseDayNumber(course,date);return(course.items||[]).filter(item=>courseItemDue(course,item,day,date))}
function courseLogValue(courseId,day,itemId){const log=data.courseLogs?.[courseId]?.[day]||{};if(log[itemId]!==undefined)return log[itemId];const match=String(itemId).match(/^ci-(\d+)$/);return match?log[match[1]]:undefined}
function courseItemComplete(item,value){if(item.scoreType==='tri')return Number(value)>=1;if(item.scoreType==='five')return Number(value)>=Math.min(5,item.target||5);if(['counter','duration'].includes(item.scoreType))return Number(value)>=Number(item.target||1);return value===true||value===1||value==='1'}
function courseScoreControl(course,item,day,compact=false){const value=courseLogValue(course.id,day,item.id),base=`data-course-id="${course.id}" data-course-day="${day}" data-course-item="${item.id}"`;if(item.scoreType==='tri')return`<div class="course-score-buttons">${[['0','نشد'],['0.5','ناقص'],['1','کامل']].map(([v,l])=>`<button ${base} data-course-value="${v}" class="${String(value)===v?'selected':''}">${l}</button>`).join('')}</div>`;if(item.scoreType==='five')return`<div class="course-score-buttons five">${[1,2,3,4,5].map(v=>`<button ${base} data-course-value="${v}" class="${Number(value)===v?'selected':''}">${faNum(v)}</button>`).join('')}</div>`;if(['counter','duration'].includes(item.scoreType))return`<div class="course-counter"><button ${base} data-course-delta="-1">−</button><strong>${faNum(Number(value)||0)}</strong><span>از ${faNum(item.target)} ${escapeHtml(item.unit)}</span><button ${base} data-course-delta="1">+</button></div>`;return`<label class="course-task"><input type="checkbox" ${base} ${value?'checked':''}><span>${compact?'انجام شد':escapeHtml(item.name)}</span></label>`}
function setCourseItemValue(courseId,day,itemId,value){data.courseLogs[courseId]=data.courseLogs[courseId]||{};data.courseLogs[courseId][day]=data.courseLogs[courseId][day]||{};data.courseLogs[courseId][day][itemId]=value;saveData();renderCourses();renderTodayCourses()}
function changeCourseItemValue(courseId,day,itemId,delta){const current=Number(courseLogValue(courseId,day,itemId))||0;setCourseItemValue(courseId,day,itemId,Math.max(0,current+delta))}
function courseProgress(course){let total=0,done=0;for(let day=1;day<=course.duration;day++){const date=addDays(new Date(`${course.start}T12:00:00`),day-1);for(const item of course.items||[]){if(item.required===false||!courseItemDue(course,item,day,date))continue;total++;if(courseItemComplete(item,courseLogValue(course.id,day,item.id)))done++}}return total?Math.round(done/total*100):0}
function renderCourseTask(course,item,day){return`<div class="course-task-card"><div class="course-task-copy"><div><strong>${escapeHtml(item.name)}</strong>${item.description?`<p>${escapeHtml(item.description)}</p>`:''}</div><small>${item.time?`ساعت ${item.time} · `:''}هدف ${faNum(item.target)} ${escapeHtml(item.unit)}${item.required?' · الزامی':' · اختیاری'}</small></div>${courseScoreControl(course,item,day,true)}</div>`}
function renderTodayCourses(){const section=document.getElementById('todayCoursesSection'),list=document.getElementById('todayCoursesList'),date=selectedDate,groups=[];(data.courses||[]).forEach(course=>{normalizeCourse(course);const day=courseDayNumber(course,date),items=courseItemsDue(course,date);if(day>=1&&day<=course.duration&&items.length)groups.push({course,day,items})});section.hidden=!groups.length;document.getElementById('todayCoursesCount').textContent=faNum(groups.reduce((n,g)=>n+g.items.length,0));list.innerHTML=groups.map(g=>`<article class="today-course-card"><header><div><strong>${escapeHtml(g.course.title)}</strong><span>روز ${faNum(g.day)} از ${faNum(g.course.duration)}</span></div><button data-open-course="${g.course.id}">مشاهده دوره</button></header>${g.items.map(item=>renderCourseTask(g.course,item,g.day)).join('')}</article>`).join('')}
function renderCourses(){const list=document.getElementById('courseList'),courses=data.courses||[];list.innerHTML='';document.getElementById('emptyCourses').hidden=courses.length>0;courses.forEach(course=>{normalizeCourse(course);const day=courseDayNumber(course),progress=courseProgress(course),items=courseItemsDue(course,startOfDay(new Date())),ended=day>course.duration,waiting=day<1;const card=document.createElement('article');card.className='course-card';const tasks=!waiting&&!ended&&items.length?items.map(item=>renderCourseTask(course,item,day)).join(''):`<div class="empty-inline">${waiting?`شروع در ${jalali(new Date(`${course.start}T12:00:00`))}`:ended?'دوره به پایان رسیده است.':'امروز تمرینی برای این دوره زمان‌بندی نشده است.'}</div>`;card.innerHTML=`<div class="course-head"><div><h3>${escapeHtml(course.title)}</h3><p>${faNum(course.duration)} روز · ${faNum(course.items.length)} زیرتمرین مستقل</p></div><div class="course-day"><strong>${ended?'✓':faNum(Math.max(0,day))}</strong><span>${ended?'پایان':'روز دوره'}</span></div></div><div class="course-progress"><span style="width:${progress}%"></span></div><small class="course-progress-label">پیشرفت کل: ${faNum(progress)}٪</small><div class="course-tasks">${tasks}</div><div class="course-actions"><button class="edit-course" data-edit-course="${course.id}">ویرایش</button><button class="delete-course" data-delete-course="${course.id}">حذف</button></div>`;list.appendChild(card)})}
function addCourseItemEditor(item={}){const row=document.createElement('article');row.className='course-item-editor';row.dataset.itemId=item.id||`ci-${Date.now()}-${Math.random().toString(36).slice(2,6)}`;row.innerHTML=`<div class="course-item-editor-head"><strong>تنظیم زیرتمرین</strong><button type="button" data-remove-course-item>×</button></div><label>نام<input data-ci-name required maxlength="80" value="${escapeHtml(item.name||'')}"></label><label>توضیحات و روش انجام<textarea data-ci-description rows="2" maxlength="1000" placeholder="توضیح، مراحل یا نکته‌های این زیرتمرین...">${escapeHtml(item.description||'')}</textarea></label><div class="form-row"><label>زمان‌بندی<select data-ci-schedule><option value="daily">هر روز</option><option value="alternate">یک روز در میان</option><option value="odd">روزهای فرد</option><option value="even">روزهای زوج</option><option value="weekdays">روزهای هفته</option><option value="specific">روزهای خاص دوره</option></select></label><label>ساعت<input data-ci-time type="time" value="${escapeHtml(item.time||'')}"></label></div><label class="ci-schedule-value">شماره روزها<input data-ci-schedule-value value="${escapeHtml(item.scheduleValue||'')}" placeholder="مثلاً 1,3,5 یا برای هفته: 0,2,4"></label><div class="form-row"><label>امتیازدهی<select data-ci-score><option value="tri">نشد / ناقص / کامل</option><option value="binary">انجام شد / نشد</option><option value="five">امتیاز ۱ تا ۵</option><option value="counter">شمارنده</option><option value="duration">مدت‌زمان</option></select></label><label>هدف یا تعداد انجام<input data-ci-target type="number" min="1" max="9999" value="${item.target||1}"></label></div><div class="form-row"><label>واحد<input data-ci-unit value="${escapeHtml(item.unit||'بار')}" maxlength="20"></label><label class="toggle-row compact"><span>الزامی</span><input data-ci-required type="checkbox" ${item.required!==false?'checked':''}></label></div>`;row.querySelector('[data-ci-schedule]').value=item.schedule||'daily';row.querySelector('[data-ci-score]').value=item.scoreType||'tri';document.getElementById('courseItemBuilder').appendChild(row)}
function readCourseItems(){return[...document.querySelectorAll('.course-item-editor')].map(row=>({id:row.dataset.itemId,name:row.querySelector('[data-ci-name]').value.trim(),description:row.querySelector('[data-ci-description]').value.trim(),schedule:row.querySelector('[data-ci-schedule]').value,scheduleValue:row.querySelector('[data-ci-schedule-value]').value.trim(),time:row.querySelector('[data-ci-time]').value,scoreType:row.querySelector('[data-ci-score]').value,target:Math.max(1,Number(row.querySelector('[data-ci-target]').value)||1),unit:row.querySelector('[data-ci-unit]').value.trim()||'بار',required:row.querySelector('[data-ci-required]').checked})).filter(x=>x.name)}
function openCourseDialog(id){const course=id?normalizeCourse(data.courses.find(x=>x.id===id)):null;document.getElementById('courseId').value=course?.id||'';document.getElementById('courseTitle').value=course?.title||'';document.getElementById('courseDuration').value=course?.duration||40;document.getElementById('courseStart').value=course?.start||iso(new Date());document.getElementById('coursePattern').value=course?.pattern||'daily';document.getElementById('courseDescription').value=course?.description||'';document.querySelectorAll('#courseWeekdays input').forEach(x=>x.checked=(course?.weekdays||[]).includes(Number(x.value)));document.getElementById('courseWeekdays').hidden=document.getElementById('coursePattern').value!=='weekdays';document.getElementById('courseItemBuilder').innerHTML='';(course?.items?.length?course.items:[{schedule:'daily',scoreType:'tri',target:1,unit:'بار',required:true}]).forEach(addCourseItemEditor);document.getElementById('courseDialog').showModal()}
function saveCourse(){const id=document.getElementById('courseId').value||`course-${Date.now()}`,items=readCourseItems(),weekdays=[...document.querySelectorAll('#courseWeekdays input:checked')].map(x=>Number(x.value));const course={id,title:document.getElementById('courseTitle').value.trim(),duration:Math.max(1,Math.min(365,Number(document.getElementById('courseDuration').value)||40)),start:document.getElementById('courseStart').value,pattern:document.getElementById('coursePattern').value,weekdays,items,description:document.getElementById('courseDescription').value.trim()};if(!course.title||!course.start||!items.length)return false;const index=data.courses.findIndex(x=>x.id===id);if(index>=0)data.courses[index]=course;else data.courses.push(course);saveData();renderCourses();renderTodayCourses();toast(index>=0?'دوره ویرایش شد':'دوره زمان‌بندی شد');return true}
function deleteCourse(id){const course=data.courses.find(x=>x.id===id);if(!course||!confirm(`دوره «${course.title}» و ثبت‌های آن حذف شود؟`))return;data.courses=data.courses.filter(x=>x.id!==id);delete data.courseLogs[id];saveData();renderCourses();renderTodayCourses();toast('دوره حذف شد')}

function renderReminderSettings(){const r=data.settings.reminders;document.getElementById('dailyReminderEnabled').checked=r.daily;document.getElementById('dailyReminderTime').value=r.dailyTime||'21:00';document.getElementById('weeklyReminderEnabled').checked=r.weekly;document.getElementById('monthlyReminderEnabled').checked=r.monthly;document.getElementById('courseReminderEnabled').checked=r.courses;document.getElementById('notificationStatus').textContent=!('Notification'in window)?'این مرورگر اعلان را پشتیبانی نمی‌کند.':Notification.permission==='granted'?'اعلان روی این دستگاه فعال است.':Notification.permission==='denied'?'اجازه اعلان در تنظیمات مرورگر مسدود شده است.':'برای دریافت اعلان، اجازهٔ سیستم لازم است.'}
function saveReminderSettings(){data.settings.reminders={daily:document.getElementById('dailyReminderEnabled').checked,dailyTime:document.getElementById('dailyReminderTime').value||'21:00',weekly:document.getElementById('weeklyReminderEnabled').checked,monthly:document.getElementById('monthlyReminderEnabled').checked,courses:document.getElementById('courseReminderEnabled').checked};saveData();toast('تنظیمات یادآوری ذخیره شد')}
function vapidBytes(value){const pad='='.repeat((4-value.length%4)%4),base64=(value+pad).replace(/-/g,'+').replace(/_/g,'/'),raw=atob(base64);return Uint8Array.from([...raw].map(c=>c.charCodeAt(0)))}
async function enableNotifications(){if(!('Notification'in window)||!('PushManager'in window))return toast('اعلان در این مرورگر پشتیبانی نمی‌شود');const permission=await Notification.requestPermission();renderReminderSettings();if(permission!=='granted')return toast('اجازه اعلان داده نشد');try{if(VAPID_PUBLIC_KEY.startsWith('__'))throw new Error('Push is not configured');const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:vapidBytes(VAPID_PUBLIC_KEY)});const json=sub.toJSON(),payload={user_id:session.user.id,endpoint:sub.endpoint,p256dh:json.keys.p256dh,auth:json.keys.auth,user_agent:navigator.userAgent,updated_at:new Date().toISOString()};const res=await cloudRequest('/rest/v1/push_subscriptions?on_conflict=endpoint',{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body:JSON.stringify(payload)});if(!res.ok)throw new Error(await res.text());await showAppNotification('تمرین‌یار','اعلان‌های پس‌زمینه با موفقیت فعال شدند.');toast('اعلان پس‌زمینه فعال شد')}catch(e){console.error(e);toast('فعال‌سازی اعلان ناموفق بود؛ دوباره تلاش کنید')}}
async function showAppNotification(title,body){if(Notification.permission!=='granted')return;const reg=await navigator.serviceWorker.ready;return reg.showNotification(title,{body,icon:'./icon.svg',badge:'./icon.svg',tag:'tamrin-yar-reminder',dir:'rtl',lang:'fa'})}
function incompleteTodayCount(){const day=data.days[iso(new Date())]||{scores:{}};return[...exerciseItems(),...nutritionItems()].filter(x=>itemScoreRatio(x,day.scores?.[x.id])<1).length}
async function checkReminders(){const r=data.settings.reminders;if(!r||Notification.permission!=='granted')return;const now=new Date(),time=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;if(time!==(r.dailyTime||'21:00'))return;const stamp=iso(now),sent=data.settings.notificationSent||{};if(r.daily&&sent.daily!==stamp){const count=incompleteTodayCount();if(count)await showAppNotification('یادآوری روزانه',`${faNum(count)} کار امروز هنوز کامل نشده است.`);sent.daily=stamp}if(r.courses&&sent.courses!==stamp){const active=(data.courses||[]).filter(c=>{const d=courseDayNumber(c,now);return courseRunsToday(c,d,now)});if(active.length)await showAppNotification('دوره‌های امروز',`برنامه امروز ${faNum(active.length)} دوره منتظر شماست.`);sent.courses=stamp}if(r.weekly&&now.getDay()===5&&sent.weekly!==stamp){await showAppNotification('جمع‌بندی هفتگی','هدف‌های این هفته را مرور و موارد باقی‌مانده را کامل کنید.');sent.weekly=stamp}const pday=Number(new Intl.DateTimeFormat('en-US-u-ca-persian',{day:'numeric'}).format(now));if(r.monthly&&pday>=29&&sent.monthly!==stamp){await showAppNotification('جمع‌بندی ماهانه','هدف‌های این ماه را پیش از پایان ماه مرور کنید.');sent.monthly=stamp}data.settings.notificationSent=sent;saveData()}

async function ensureProfile(){const id=session.user.id,username=session.username||session.user.email?.split('@')[0]||`user-${id.slice(0,6)}`;let res=await cloudRequest(`/rest/v1/profiles?select=*&user_id=eq.${id}`);if(!res.ok)return null;const rows=await res.json();if(rows[0]){coachProfile=rows[0];if(coachProfile.username!==username)await cloudRequest(`/rest/v1/profiles?user_id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({username,updated_at:new Date().toISOString()})});return coachProfile}res=await cloudRequest('/rest/v1/profiles',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({user_id:id,username,display_name:username,role:'student'})});if(!res.ok)return null;coachProfile=(await res.json())[0];return coachProfile}
function studentSummary(record){const remote=record.data||{},today=iso(new Date()),scores=remote.days?.[today]?.scores||{},custom=(remote.settings?.customItems||[]).filter(x=>x.active!==false&&!['weekly','monthly'].includes(x.schedule)),legacy=remote.settings?.showLegacyDefaults?12:0;let complete=Object.values(scores).filter(v=>Number(v)>=1).length,total=custom.length+legacy;custom.forEach(item=>{const raw=scores[item.id];if(raw!==undefined&&Number(raw)>=1&&!itemScoreRatio(item,raw))complete--});complete=Math.min(total,Math.max(0,complete));const percent=total?Math.round(complete/total*100):0,activeCourses=(remote.courses||[]).filter(c=>{const day=courseDayNumber(c);return day>=1&&day<=Number(c.duration||0)}).length;return{complete,total,percent,activeCourses,updatedAt:record.updated_at}}
function reviewStatusLabel(status){return status==='approved'?'تأیید شده':'نیازمند اصلاح'}
function renderStudentCoach(){const root=document.getElementById('coachContent');document.getElementById('coachHeading').textContent='ارتباط با استاد';document.getElementById('coachIntro').textContent='با کد استاد متصل شوید و بازخوردهای ثبت‌شده را ببینید.';const relation=coachStudents[0],teacher=relation?.teacher,reviews=coachReviews||[];root.innerHTML=`<section class="coach-panel"><h3>${teacher?'استاد متصل':'اتصال به استاد'}</h3>${teacher?`<p>گزارش انجام تمرین‌های شما برای <strong>${escapeHtml(teacher.display_name||teacher.username)}</strong> قابل مشاهده است.</p>`:`<p>کدی را که استاد در اختیار شما گذاشته وارد کنید.</p><form id="connectTeacherForm" class="connect-form"><input id="teacherCodeInput" required maxlength="32" placeholder="کد استاد"><button>اتصال</button></form>`}<div class="privacy-note">یادداشت خصوصی روزانه، رمز عبور و اطلاعات ورود برای استاد نمایش داده نمی‌شود.</div></section><div>${reviews.length?reviews.map(r=>`<article class="feedback-card ${r.status}"><header><strong>${reviewStatusLabel(r.status)}</strong><small>${jalali(new Date(`${r.review_date}T12:00:00`))}</small></header><p>${escapeHtml(r.comment||'بدون توضیح')}</p></article>`).join(''):`<div class="empty-state"><strong>هنوز بازخوردی ثبت نشده است</strong><span>پس از بررسی استاد، نتیجه اینجا نمایش داده می‌شود.</span></div>`}</div>`;const form=document.getElementById('connectTeacherForm');if(form)form.onsubmit=async e=>{e.preventDefault();await connectTeacher()}}
function renderTeacherCoach(selectedId=coachStudents[0]?.user_id){const root=document.getElementById('coachContent');document.getElementById('coachHeading').textContent='داشبورد استاد';document.getElementById('coachIntro').textContent='گزارش امروز هنرجویان را بررسی و بازخورد ثبت کنید.';const selected=coachStudents.find(x=>x.user_id===selectedId);root.innerHTML=`<section class="coach-panel"><h3>کد اتصال شما</h3><div class="teacher-code"><span>این کد را به هنرجو بدهید</span><strong>${escapeHtml(coachProfile.teacher_code||'—')}</strong></div></section>${coachStudents.length?`<div class="student-select">${coachStudents.map(s=>`<button data-student-select="${s.user_id}" class="${s.user_id===selectedId?'active':''}">${escapeHtml(s.display_name||s.username)}</button>`).join('')}</div>`:'<div class="empty-state"><strong>هنرجویی متصل نشده است</strong><span>کد بالا را در اختیار هنرجو قرار دهید.</span></div>'}${selected?renderStudentReport(selected):''}`}
function renderStudentReport(student){const s=studentSummary(student.record),today=iso(new Date()),review=coachReviews.find(r=>r.student_id===student.user_id&&r.review_date===today);return`<article class="student-report"><h3>${escapeHtml(student.display_name||student.username)}</h3><p>گزارش امروز · ${jalali(new Date())}</p><div class="report-metrics"><div><strong>${faNum(s.percent)}٪</strong><span>پیشرفت امروز</span></div><div><strong>${faNum(s.complete)} / ${faNum(s.total)}</strong><span>موارد کامل</span></div><div><strong>${faNum(s.activeCourses)}</strong><span>دوره فعال</span></div></div><p>آخرین همگام‌سازی: ${s.updatedAt?new Intl.DateTimeFormat('fa-IR',{dateStyle:'short',timeStyle:'short'}).format(new Date(s.updatedAt)):'نامشخص'}</p><form class="review-form" data-review-form="${student.user_id}"><textarea rows="4" maxlength="1500" placeholder="نظر، راهنمایی یا اصلاح لازم…">${escapeHtml(review?.comment||'')}</textarea><div class="review-actions"><button type="button" data-review-status="approved">تأیید تمرین‌ها</button><button type="button" data-review-status="revision">نیازمند اصلاح</button></div></form><div class="privacy-note">یادداشت خصوصی هنرجو در این گزارش نمایش داده نمی‌شود.</div></article>`}
async function connectTeacher(){const code=document.getElementById('teacherCodeInput').value.trim();if(!code)return;const res=await cloudRequest('/rest/v1/rpc/connect_teacher',{method:'POST',body:JSON.stringify({connection_code:code})});if(!res.ok){toast('کد استاد معتبر نیست');return}toast('اتصال به استاد انجام شد');await loadCoachView()}
async function saveTeacherReview(studentId,status){const form=document.querySelector(`[data-review-form="${studentId}"]`),comment=form?.querySelector('textarea').value.trim()||'',payload={teacher_id:session.user.id,student_id:studentId,review_date:iso(new Date()),status,comment,updated_at:new Date().toISOString()};const res=await cloudRequest('/rest/v1/teacher_reviews?on_conflict=teacher_id,student_id,review_date',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(payload)});if(!res.ok){toast('ثبت بازخورد ناموفق بود');return}toast(status==='approved'?'تمرین‌ها تأیید شد':'درخواست اصلاح ثبت شد');await loadCoachView(studentId)}
async function loadCoachView(selectedId){const root=document.getElementById('coachContent');root.innerHTML='<div class="empty-state"><strong>در حال دریافت اطلاعات…</strong></div>';coachProfile=coachProfile||await ensureProfile();if(!coachProfile){root.innerHTML='<div class="empty-state"><strong>بخش استاد هنوز فعال نشده است</strong><span>ساختار دیتابیس باید یک‌بار نصب شود.</span></div>';return}if(coachProfile.role==='teacher'){const linksRes=await cloudRequest(`/rest/v1/student_teachers?select=student_id&teacher_id=eq.${session.user.id}`),links=linksRes.ok?await linksRes.json():[],ids=links.map(x=>x.student_id);coachStudents=[];coachReviews=[];if(ids.length){const filter=ids.join(','),[profilesRes,dataRes,reviewsRes]=await Promise.all([cloudRequest(`/rest/v1/profiles?select=user_id,username,display_name&user_id=in.(${filter})`),cloudRequest(`/rest/v1/user_data?select=user_id,data,updated_at&user_id=in.(${filter})`),cloudRequest(`/rest/v1/teacher_reviews?select=*&teacher_id=eq.${session.user.id}&order=review_date.desc`)]),profiles=profilesRes.ok?await profilesRes.json():[],records=dataRes.ok?await dataRes.json():[];coachReviews=reviewsRes.ok?await reviewsRes.json():[];coachStudents=profiles.map(p=>({...p,record:records.find(r=>r.user_id===p.user_id)||{user_id:p.user_id,data:{},updated_at:null}}))}renderTeacherCoach(selectedId)}else{const linksRes=await cloudRequest(`/rest/v1/student_teachers?select=teacher_id&student_id=eq.${session.user.id}`),links=linksRes.ok?await linksRes.json():[];coachStudents=[];if(links[0]){const teacherRes=await cloudRequest(`/rest/v1/profiles?select=user_id,username,display_name&user_id=eq.${links[0].teacher_id}`),teachers=teacherRes.ok?await teacherRes.json():[];coachStudents=[{...links[0],teacher:teachers[0]}]}const reviewsRes=await cloudRequest(`/rest/v1/teacher_reviews?select=*&student_id=eq.${session.user.id}&order=review_date.desc`);coachReviews=reviewsRes.ok?await reviewsRes.json():[];renderStudentCoach()}}

function authHeaders(token=session?.access_token){return{'apikey':SUPABASE_KEY,'Authorization':`Bearer ${token||SUPABASE_KEY}`,'Content-Type':'application/json'}}
async function refreshSession(){if(!session?.refresh_token)return false;const res=await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{'apikey':SUPABASE_KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});if(!res.ok)return false;const next=await res.json();session={...session,...next};localStorage.setItem(SESSION_KEY,JSON.stringify(session));return true}
async function cloudRequest(path,options={},retry=true){let res=await fetch(`${SUPABASE_URL}${path}`,{...options,headers:{...authHeaders(),...(options.headers||{})}});if(res.status===401&&retry&&await refreshSession())res=await cloudRequest(path,options,false);return res}
async function login(username,password){const safe=username.trim().toLowerCase();if(!/^[a-z0-9._-]{3,32}$/.test(safe))throw new Error('نام کاربری باید ۳ تا ۳۲ حرف لاتین یا عدد باشد.');const res=await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`,{method:'POST',headers:{'apikey':SUPABASE_KEY,'Content-Type':'application/json'},body:JSON.stringify({email:`${safe}@users.tamrinyar.app`,password})});if(!res.ok)throw new Error('نام کاربری یا رمز عبور صحیح نیست.');session=await res.json();session.username=safe;localStorage.setItem(SESSION_KEY,JSON.stringify(session));await startSession()}
function migrateEditableDefaults(){if(!data.settings.showLegacyDefaults)return false;const records=[...builtInExercises.map(item=>({...item,category:'تمرین',description:item.hint||'',schedule:item.alternate?'alternate':'daily',target:Number(item.hint?.match(/\d+/)?.[0])||1,unit:item.hint?.includes('دقیقه')?'دقیقه':item.hint?.includes('تکرار')?'تکرار':'بار',time:'',scoreType:'tri',active:true})),...builtInNutrition.map(item=>({...item,kind:'nutrition',category:'تغذیه',description:item.hint||'',schedule:'daily',target:1,unit:'بار',time:'',scoreType:'tri',active:true})),{id:'cardio',name:'هوازی',category:'ورزش',description:'هدف هفتگی هوازی',schedule:'weekly',target:2,unit:'بار',time:'',scoreType:'counter',active:true},{id:'hypnosis',name:'خودهیپنوتیزم',category:'مراقبه',description:'هدف هفتگی خودهیپنوتیزم',schedule:'weekly',target:2,unit:'بار',time:'',scoreType:'counter',active:true},{id:'omega',name:'Omega 3',category:'تغذیه',description:'برنامه هفتگی مکمل امگا ۳',schedule:'weekly',target:4,unit:'عدد',time:'',scoreType:'counter',active:true}];records.forEach(item=>{if(!data.settings.customItems.some(x=>x.id===item.id))data.settings.customItems.push(item)});data.settings.showLegacyDefaults=false;data.settings.editableDefaultsV20=true;return true}
async function loadCloud(){const res=await cloudRequest(`/rest/v1/user_data?select=data&user_id=eq.${session.user.id}`);if(!res.ok)throw new Error('دریافت اطلاعات ناموفق بود');const rows=await res.json(),legacy=takeOwnerLegacyData();if(legacy){data=legacy;saveLocalData();await syncCloud()}else if(rows[0]?.data){data=loadCloudShape(rows[0].data);saveLocalData()}else{data=freshData();saveLocalData();await syncCloud()}if(isOwnerSession()&&!data.settings.ownerInitialized){data.settings.showLegacyDefaults=true;data.settings.ownerInitialized=true}if(migrateEditableDefaults()){saveLocalData();await syncCloud()}renderToday()}
function loadCloudShape(value){value.days=value.days||{};value.weeks=value.weeks||{};value.months=value.months||{};value.courses=(value.courses||[]).map(normalizeCourse);value.courseLogs=value.courseLogs||{};value.settings=value.settings||{};value.settings.customItems=(value.settings.customItems||[]).map(item=>({...item,description:item.description||'',time:item.time||'',scoreType:item.scoreType||(['weekly','monthly'].includes(item.schedule)?'counter':'tri')}));value.settings.showLegacyDefaults=value.settings.showLegacyDefaults===true;value.settings.reminders={daily:false,dailyTime:'21:00',weekly:false,monthly:false,courses:false,...(value.settings.reminders||{})};return value}
async function syncCloud(){if(!session)return;const status=document.getElementById('cloudStatus');if(status)status.textContent='در حال همگام‌سازی…';try{const res=await cloudRequest('/rest/v1/user_data?on_conflict=user_id',{method:'POST',headers:{'Prefer':'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:session.user.id,data,updated_at:new Date().toISOString()})});if(!res.ok)throw new Error();await dailyBackup();if(status)status.textContent=`آخرین همگام‌سازی: ${new Intl.DateTimeFormat('fa-IR',{hour:'2-digit',minute:'2-digit'}).format(new Date())}`}catch{if(status)status.textContent='همگام‌سازی ناموفق؛ اطلاعات روی دستگاه محفوظ است.'}}
async function dailyBackup(){const today=iso(new Date());if(data.settings.lastCloudBackup===today)return;const res=await cloudRequest('/rest/v1/daily_backups?on_conflict=user_id,backup_date',{method:'POST',headers:{'Prefer':'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:session.user.id,backup_date:today,data})});if(res.ok){data.settings.lastCloudBackup=today;saveLocalData()}}
async function loadLibrary(){const res=await cloudRequest('/rest/v1/exercise_library?select=*&order=title_fa');if(res.ok){libraryItems=await res.json();renderLibrary()}}
async function startSession(){const message=document.getElementById('loginMessage');message.textContent='در حال آماده‌سازی اطلاعات…';await Promise.all([loadCloud(),loadLibrary()]);await dailyBackup();document.getElementById('appShell').hidden=false;document.getElementById('loginScreen').hidden=true;message.textContent=''}
function logout(){session=null;data=freshData();coachProfile=null;coachStudents=[];coachReviews=[];localStorage.removeItem(SESSION_KEY);document.getElementById('loginPassword').value='';document.getElementById('appShell').hidden=true;document.getElementById('loginScreen').hidden=false}

document.addEventListener('click',e=>{const score=e.target.closest('[data-id][data-score]');if(score)setScore(score.dataset.id,score.dataset.score);const itemDelta=e.target.closest('[data-item-delta]');if(itemDelta)changeDailyItemValue(itemDelta.dataset.id,Number(itemDelta.dataset.itemDelta));const counter=e.target.closest('[data-counter]');if(counter)changeCounter(counter.dataset.counter,Number(counter.dataset.delta));const monthCounter=e.target.closest('[data-month-counter]');if(monthCounter)changeMonthCounter(monthCounter.dataset.monthCounter,Number(monthCounter.dataset.delta));const nav=e.target.closest('.nav-item');if(nav)switchView(nav.dataset.view);const edit=e.target.closest('[data-edit-item]');if(edit)openItemDialog(edit.dataset.editItem);const archive=e.target.closest('[data-archive-item]');if(archive)archiveItem(archive.dataset.archiveItem);const remove=e.target.closest('[data-delete-item]');if(remove)deleteItem(remove.dataset.deleteItem);const add=e.target.closest('[data-add-library]');if(add)addFromLibrary(add.dataset.addLibrary);const editLibrary=e.target.closest('[data-edit-library]');if(editLibrary)openLibraryEdit(editLibrary.dataset.editLibrary);const courseValue=e.target.closest('[data-course-value]');if(courseValue)setCourseItemValue(courseValue.dataset.courseId,Number(courseValue.dataset.courseDay),courseValue.dataset.courseItem,Number(courseValue.dataset.courseValue));const courseDelta=e.target.closest('[data-course-delta]');if(courseDelta)changeCourseItemValue(courseDelta.dataset.courseId,Number(courseDelta.dataset.courseDay),courseDelta.dataset.courseItem,Number(courseDelta.dataset.courseDelta));const openCourse=e.target.closest('[data-open-course]');if(openCourse)switchView('coursesView');const removeCourseItem=e.target.closest('[data-remove-course-item]');if(removeCourseItem)removeCourseItem.closest('.course-item-editor').remove();const editCourse=e.target.closest('[data-edit-course]');if(editCourse)openCourseDialog(editCourse.dataset.editCourse);const deleteCourseButton=e.target.closest('[data-delete-course]');if(deleteCourseButton)deleteCourse(deleteCourseButton.dataset.deleteCourse);const studentButton=e.target.closest('[data-student-select]');if(studentButton)renderTeacherCoach(studentButton.dataset.studentSelect);const reviewButton=e.target.closest('[data-review-status]');if(reviewButton){const form=reviewButton.closest('[data-review-form]');if(form)saveTeacherReview(form.dataset.reviewForm,reviewButton.dataset.reviewStatus)}});
document.addEventListener('change',e=>{if(e.target.matches('input[data-course-id][type="checkbox"]'))setCourseItemValue(e.target.dataset.courseId,Number(e.target.dataset.courseDay),e.target.dataset.courseItem,e.target.checked);if(e.target.matches('#dailyReminderEnabled,#dailyReminderTime,#weeklyReminderEnabled,#monthlyReminderEnabled,#courseReminderEnabled'))saveReminderSettings()});
document.getElementById('prevDay').onclick=()=>{selectedDate=addDays(selectedDate,-1);renderToday()};document.getElementById('nextDay').onclick=()=>{selectedDate=addDays(selectedDate,1);renderToday()};document.getElementById('goToday').onclick=()=>{selectedDate=startOfDay(new Date());renderToday()};document.getElementById('dateButton').onclick=()=>{selectedDate=startOfDay(new Date());renderToday()};
document.getElementById('dayNote').addEventListener('input',e=>{getDay().note=e.target.value;saveData()});document.getElementById('exportCsv').onclick=exportCsv;document.getElementById('backupJson').onclick=()=>download(JSON.stringify({version:1,exportedAt:new Date().toISOString(),data},null,2),'tamrin-yar-backup.json','application/json');
document.getElementById('restoreJson').onchange=async e=>{try{const parsed=JSON.parse(await e.target.files[0].text());if(!parsed.data?.days||!parsed.data?.weeks)throw new Error();data=loadCloudShape(parsed.data);saveData();renderToday();toast('پشتیبان بازیابی شد')}catch{toast('فایل پشتیبان معتبر نیست')}e.target.value=''};
document.getElementById('clearData').onclick=()=>{if(confirm('همه ثبت‌ها، فعالیت‌های شخصی و یادداشت‌ها پاک شوند؟')){data={days:{},weeks:{},months:{},settings:{customItems:[],showLegacyDefaults:false}};saveData();renderToday();renderTrend();renderManage();toast('اطلاعات پاک شد')}};
document.getElementById('addItemBtn').onclick=()=>openItemDialog();document.getElementById('closeDialog').onclick=()=>document.getElementById('itemDialog').close();document.getElementById('itemForm').addEventListener('submit',e=>{if(!saveItem())e.preventDefault()});
document.getElementById('addCourseBtn').onclick=()=>openCourseDialog();document.getElementById('addCourseItemBtn').onclick=()=>{const schedule=document.getElementById('coursePattern').value,scheduleValue=schedule==='weekdays'?[...document.querySelectorAll('#courseWeekdays input:checked')].map(x=>x.value).join(','):'';addCourseItemEditor({schedule,scheduleValue,scoreType:'tri',target:1,unit:'بار',required:true})};document.getElementById('closeCourseDialog').onclick=()=>document.getElementById('courseDialog').close();document.getElementById('coursePattern').onchange=e=>document.getElementById('courseWeekdays').hidden=e.target.value!=='weekdays';document.getElementById('courseForm').addEventListener('submit',e=>{if(!saveCourse())e.preventDefault()});document.getElementById('enableNotifications').onclick=enableNotifications;
document.getElementById('closeLibraryEditDialog').onclick=()=>document.getElementById('libraryEditDialog').close();document.getElementById('libraryEditForm').addEventListener('submit',async e=>{e.preventDefault();if(await saveLibraryEdit())document.getElementById('libraryEditDialog').close()});
document.getElementById('loginForm').addEventListener('submit',async e=>{e.preventDefault();const message=document.getElementById('loginMessage');message.textContent='در حال ورود…';try{await login(document.getElementById('loginUsername').value,document.getElementById('loginPassword').value);message.textContent=''}catch(err){message.textContent=err.message||'ورود ناموفق بود.'}});document.getElementById('logoutBtn').onclick=logout;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;document.getElementById('installBtn').hidden=false});document.getElementById('installBtn').onclick=async()=>{if(!deferredInstall)return;deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;document.getElementById('installBtn').hidden=true};
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js'));
renderToday();setInterval(checkReminders,30000);if(session)startSession().then(()=>{renderCourses();renderReminderSettings();checkReminders()}).catch(()=>logout());
